# Add a period. Validate first so a bad name or date is a 400, not a 404.
# A viewer may change nothing: refused before anything is read or written.
viewer:
  class: net.officefloor.hq.app.role.CheckCanChange
  next: validate
validate:
  class: net.officefloor.hq.app.period.ValidatePeriod
  next: load
load:
  class: net.officefloor.hq.app.sheet.LoadSheet
  govern: [ transaction ]
  next: build
# Against the sheet: a blank from-date is its today; the name is unused and no period overlaps.
build:
  class: net.officefloor.hq.app.period.BuildPeriod
  govern: [ transaction ]
  next: save
save:
  class: net.officefloor.hq.app.period.SavePeriod
  govern: [ transaction ]
  next: audit
# Last before the response: every rule has passed and the change is saved.
audit:
  class: net.officefloor.hq.app.period.AuditPeriodAdded
  govern: [ transaction ]
  next: respond
respond:
  class: net.officefloor.hq.app.period.RespondWithPeriod
  govern: [ transaction ]
=== ValidatePeriod
package net.officefloor.hq.app.period;

import java.time.LocalDate;
import java.time.format.DateTimeParseException;
import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.RequestBody;

public class ValidatePeriod {
    public void validate(@RequestBody PeriodRequest request, Out<PeriodInput> body)
            throws InvalidPeriodException {
        String name = request == null || request.name() == null ? "" : request.name().trim();
        if (name.isEmpty()) throw new InvalidPeriodException("A period's name is required");
        if (name.length() > 200) throw new InvalidPeriodException("A period's name is at most 200 characters");
        LocalDate from = date(request.from(), "from");
        LocalDate to = date(request.to(), "to");
        if (to == null) throw new InvalidPeriodException("A to-date is required");
        body.set(new PeriodInput(name, from, to));
    }

    private static LocalDate date(String raw, String which) throws InvalidPeriodException {
        String value = raw == null ? "" : raw.trim();
        if (value.isEmpty()) return null;
        try {
            return LocalDate.parse(value);
        } catch (DateTimeParseException e) {
            throw new InvalidPeriodException("A " + which + "-date is a date, yyyy-MM-dd");
        }
    }
}
=== BuildPeriod
package net.officefloor.hq.app.period;

import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;

/**
 * Builds the period, a blank from-date taking the sheet's today, and checks it against the sheet:
 * its to-date not before its from-date, its name not already used, and no day shared with another
 * period.
 */
public class BuildPeriod {
    public void build(@Val PeriodInput input, @Val Sheet sheet, PeriodRepository repository,
            Out<Period> periodOut) throws InvalidPeriodException {
        Period period = new Period(sheet.id(), input.name(),
                input.from() == null ? sheet.today() : input.from(), input.to());
        if (period.to().isBefore(period.from())) {
            throw new InvalidPeriodException("A period's to-date is on or after its from-date");
        }
        for (Period other : repository.findAll(sheet.id())) {
            if (other.name().equals(period.name())) {
                throw new InvalidPeriodException("There is already a period named " + period.name());
            }
            if (other.overlaps(period)) {
                throw new InvalidPeriodException("A period may not overlap period " + other.name());
            }
        }
        periodOut.set(period);
    }
}
