import { useQuery } from '@tanstack/react-query';
import { getJson } from '../../api/http';
import { countedOn } from '../claims/claims';
import type { Claim } from '../claims/claims';
import { gradeOn } from '../people/people';
import type { Person } from '../people/people';
import { claimDue, rateOn, sumDue } from '../rates/rates';
import type { Dated, Late, Rate } from '../rates/rates';

/**
 * A period: its name (unique on the sheet), its from and to dates (yyyy-MM-dd), inclusive, whether
 * it is closed, the due-total fixed when it was closed ('' while open), and each person's due-total
 * fixed when it was closed, by person id (empty while open).
 */
export type Period = {
  name: string;
  from: string;
  to: string;
  closed: boolean;
  closedTotal: string;
  personTotals: Record<string, string>;
};

export const periodsKey = (sheetId: string) => ['sheet', sheetId, 'periods'] as const;

/** The sheet's periods, by from-date. */
export function usePeriods(sheetId: string) {
  return useQuery({
    queryKey: periodsKey(sheetId),
    queryFn: async () =>
      (await getJson<{ periods: Period[] }>(`/api/sheets/${encodeURIComponent(sheetId)}/periods`)).periods,
  });
}

/** The period whose dates contain the date (yyyy-MM-dd), or null when none does. */
export function periodOf(periods: Period[], date: string): Period | null {
  return periods.find((p) => p.from <= date && date <= p.to) ?? null;
}

/**
 * A person's due-total for a period: the one fixed when it was closed (0.00 for a person added
 * after), else the due as shown now of their claims dated in it that counted at the end of its last
 * day, by the status their log records then, added up.
 */
export function personPeriodDueTotal(
  period: Period,
  person: Person,
  claims: Claim[],
  rates: Rate[],
  floor: Dated,
  late: Late,
): string {
  if (period.closed) return period.personTotals[person.id] ?? '0.00';
  return sumDue(
    claims
      .filter((c) => c.personId === person.id && countedOn(c, period.to, person.holds, late.today) && period.from <= c.date && c.date <= period.to)
      .map((c) => claimDue(c, rateOn(rates, gradeOn(person.grades, c.date), c.date), floor, late)),
  );
}

/** A period's due-total: the people's due-totals for it, added up. */
export function periodDueTotal(
  period: Period,
  people: Person[],
  claims: Claim[],
  rates: Rate[],
  floor: Dated,
  late: Late,
): string {
  return sumDue(people.map((person) => personPeriodDueTotal(period, person, claims, rates, floor, late)));
}
import { useState } from 'react';
import type { FormEvent } from 'react';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { useOnce } from '../../query/useOnce';
import { postJson } from '../../api/http';
import { SheetBody } from '../../slots/defs/sheetBody';
import { useClaims } from '../claims/claims';
import { usePeople } from '../people/people';
import { useUser } from '../session/session';
import { useRates } from '../rates/rates';
import { useFloor, useLate } from '../access/access';
import { periodDueTotal, periodsKey, usePeriods } from './periods';
import type { Period } from './periods';

type Fields = { name: string; from: string; to: string };
const EMPTY: Fields = { name: '', from: '', to: '' };

// The sheet's periods: a form that adds one (a from-date left blank is the sheet's today), and each
// period with its due-total: the due of the claims dated in it that counted at its end (by their status log), fixed when the
// period is closed. A closed period's claims cannot be changed. A steward may reopen a closed period.
function Periods({ sheetId }: { sheetId: string }) {
  const queryClient = useQueryClient();
  const periods = usePeriods(sheetId);
  const people = usePeople(sheetId).data ?? [];
  const claims = useClaims(sheetId).data ?? [];
  const floor = useFloor(sheetId);
  const late = useLate(sheetId);
  const rates = useRates(sheetId).data ?? [];
  const [fields, setFields] = useState<Fields>(EMPTY);
  const [error, setError] = useState('');
  const [user] = useUser();

  const [refused, setRefused] = useState<{ name: string; action: 'close' | 'reopen' } | null>(null);

  const once = useOnce();
  const close = useMutation({
    mutationFn: (name: string) =>
      postJson<Period>(
        `/api/sheets/${encodeURIComponent(sheetId)}/periods/${encodeURIComponent(name)}/close`,
        {},
        user,
      ),
    onSuccess: () => {
      void queryClient.invalidateQueries({ queryKey: periodsKey(sheetId) });
    },
    onError: (_e, name) => setRefused({ name, action: 'close' }),
  });

  const closePeriod = (name: string) => {
    setRefused(null);
    once((done) => close.mutate(name, { onSettled: done }));
  };

  // Only a steward may reopen a closed period; its due-total is then live again.
  const reopen = useMutation({
    mutationFn: (name: string) =>
      postJson<Period>(
        `/api/sheets/${encodeURIComponent(sheetId)}/periods/${encodeURIComponent(name)}/reopen`,
        {},
        user,
      ),
    onSuccess: () => {
      void queryClient.invalidateQueries({ queryKey: periodsKey(sheetId) });
    },
    onError: (_e, name) => setRefused({ name, action: 'reopen' }),
  });

  const reopenPeriod = (name: string) => {
    setRefused(null);
    once((done) => reopen.mutate(name, { onSettled: done }));
  };

  const save = useMutation({
    mutationFn: (body: Fields) =>
      postJson<Period>(`/api/sheets/${encodeURIComponent(sheetId)}/periods`, body, user),
    onSuccess: () => {
      setFields(EMPTY);
      void queryClient.invalidateQueries({ queryKey: periodsKey(sheetId) });
    },
    onError: () => setError('That period could not be added.'),
  });

  const submit = (e: FormEvent) => {
    e.preventDefault();
    setError('');
    const body = { name: fields.name.trim(), from: fields.from.trim(), to: fields.to.trim() };
    if (body.name === '') {
      setError('A name is required.');
      return;
    }
    if (body.to === '') {
      setError('A to-date is required.');
      return;
    }
    once((done) => save.mutate(body, { onSettled: done }));
  };

  const change = (next: Partial<Fields>) => {
    setFields((f) => ({ ...f, ...next }));
    setError('');
  };


  return (
    <section data-testid="periods">
      <h2>Periods</h2>
      <form onSubmit={submit} data-testid="period-form">
        <label>
          Name{' '}
          <input data-testid="period-form-name" value={fields.name} onChange={(e) => change({ name: e.target.value })} />
        </label>{' '}
        <label>
          From{' '}
          <input
            type="date"
            data-testid="period-form-from"
            value={fields.from}
            onChange={(e) => change({ from: e.target.value })}
          />
        </label>{' '}
        <label>
          To{' '}
          <input
            type="date"
            data-testid="period-form-to"
            value={fields.to}
            onChange={(e) => change({ to: e.target.value })}
          />
        </label>{' '}
        <button type="submit" data-testid="period-form-submit" disabled={save.isPending}>
          Add period
        </button>
        {error && (
          <p role="alert" data-testid="period-form-error">
            {error}
          </p>
        )}
      </form>
      {periods.isError && (
        <p role="alert" data-testid="periods-error">
          The periods could not be read.
        </p>
      )}
      <table data-testid="period-list">
        <thead>
          <tr>
            <th>Period</th>
            <th>From</th>
            <th>To</th>
            <th>Due</th>
            <th>Closed</th>
            <th></th>
          </tr>
        </thead>
        <tbody>
          {(periods.data ?? []).map((p) => (
            <tr key={p.name} data-testid={`period-row-${p.name}`}>
              <td data-testid="period-name">{p.name}</td>
              <td data-testid="period-from">{p.from}</td>
              <td data-testid="period-to">{p.to}</td>
              <td data-testid="period-due-total">{periodDueTotal(p, people, claims, rates, floor, late)}</td>
              <td data-testid="period-closed">{p.closed ? 'yes' : 'no'}</td>
              <td>
                <button
                  type="button"
                  data-testid="period-close"
                  disabled={close.isPending}
                  onClick={() => closePeriod(p.name)}
                >
                  Close
                </button>{' '}
                <button
                  type="button"
                  data-testid="period-reopen"
                  disabled={reopen.isPending}
                  onClick={() => reopenPeriod(p.name)}
                >
                  Reopen
                </button>
                {refused?.name === p.name && (
                  <p role="alert" data-testid="period-error">
                    {refused.action === 'close' ? 'That period could not be closed.' : 'That period could not be reopened.'}
                  </p>
                )}
              </td>
            </tr>
          ))}
        </tbody>
      </table>
    </section>
  );
}

export const contribution = SheetBody.fill({ order: -5, Component: Periods });
